document.querySelector('#startBtn').addEventListener('click',startRace);document.querySelector('#againBtn').addEventListener('click',startRace);

function placeCar(car,distance,offset,steerAngle=0){const t=((distance%trackLength)+trackLength)%trackLength/trackLength,f=frameAt(t),pos=f.p.clone().addScaledVector(f.side,offset);car.root.position.set(pos.x,.02,pos.z);car.root.rotation.y=Math.atan2(f.tan.x,f.tan.z)+steerAngle;}
function rank(){let ahead=0;for(const r of rivals)if(r.distance>playerDistance)ahead++;return 4-ahead}
function finishRace(){running=false;finished=true;document.querySelector('#resultTitle').textContent=rank()===1?'RACE WINNER':'RACE COMPLETE';document.querySelector('#resultPos').textContent=`P${rank()} / 4`;document.querySelector('#resultTime').textContent=fmtTime(elapsed);document.querySelector('#resultLap').textContent=bestLap<Infinity?fmtTime(bestLap):'—';document.querySelector('#results').classList.add('show')}
const cameraTarget=new THREE.Vector3(),lookTarget=new THREE.Vector3();
function update(dt){if(running){elapsed+=dt;
  const acceleration=input.gas?31:0,braking=input.brake?52:0,boosting=input.boost&&boostFuel>0&&speed>7;
  if(boosting)boostFuel=Math.max(0,boostFuel-dt*.24);else boostFuel=Math.min(1,boostFuel+dt*.075);
  speed+=((acceleration+(boosting?28:0))-braking-speed*(input.gas||input.brake?.09:.22))*dt;
  speed=THREE.MathUtils.clamp(speed,0,boosting?91:78);
  const steerInput=(input.right?1:0)-(input.left?1:0);steer=THREE.MathUtils.damp(steer,steerInput,8,dt);
  lateral+=steer*dt*(2.1+speed*.11);lateral=THREE.MathUtils.damp(lateral,0,Math.abs(steerInput)>.1?.15:1.5,dt);
  if(Math.abs(lateral)>5.9)speed=Math.max(speed-22*dt,12);
  lateral=THREE.MathUtils.clamp(lateral,-7.2,7.2);
  const oldLap=Math.floor(playerDistance/trackLength);playerDistance+=speed*dt;const newLap=Math.floor(playerDistance/trackLength);
  if(newLap>oldLap){lap++;const lapTime=elapsed-lapStart;lapStart=elapsed;if(lapTime<bestLap)bestLap=lapTime;if(lap>=totalLaps){finishRace()}}
  for(const r of rivals){r.distance+=r.speed*dt;const rt=((r.distance%trackLength)+trackLength)%trackLength/trackLength;const rf=frameAt(rt);if(Math.abs(r.lane)>7)r.lane*=.8;placeCar(r.car,r.distance,r.lane,0)}
  placeCar(player,playerDistance,lateral,steer*.13);
  const rawpct=(playerDistance%(trackLength*totalLaps))/(trackLength*totalLaps);document.querySelector('#progressBar').style.width=`${rawpct*100}%`;document.querySelector('#progressText').textContent=`${Math.floor(rawpct*100)}%`;document.querySelector('#lapCurrent').textContent=String(Math.min(lap+1,totalLaps)).padStart(2,'0');document.querySelector('#position').textContent=String(rank()).padStart(2,'0');document.querySelector('#speed').innerHTML=`${String(Math.round(speed*3.6)).padStart(3,'0')}<small>KM/H</small>`;document.querySelector('#timer').textContent=fmtTime(elapsed);document.querySelector('#bestTime').textContent=bestLap<Infinity?`BEST  ${fmtTime(bestLap)}`:'BEST  —:—.———';
 }
 // Always frame the car: cinematic parked-car presentation becomes an over-shoulder race view.
 const t=((playerDistance%trackLength)+trackLength)%trackLength/trackLength,f=frameAt(t);const carPos=player.root.position;const backDist=running?11.8:14.8,height=running?5.4:7.2;cameraTarget.set(carPos.x-f.tan.x*backDist+f.side.x*(running?lateral*.14:2),height,carPos.z-f.tan.z*backDist+f.side.z*(running?lateral*.14:2));camera.position.lerp(cameraTarget,1-Math.exp(-dt*(running?4.8:1.5)));lookTarget.set(carPos.x+f.tan.x*7,1.2,carPos.z+f.tan.z*7);camera.lookAt(lookTarget);camera.fov=THREE.MathUtils.damp(camera.fov,running?54+speed*.055:52,2,dt);camera.updateProjectionMatrix();
}
// Give the opening scene a real car, track and skyline before the green flag.
placeCar(player,0,0);rivals.forEach(r=>placeCar(r.car,r.distance,r.lane));
function animate(stamp){requestAnimationFrame(animate);const dt=Math.min(.04,(stamp-prevStamp)/1000||.016);prevStamp=stamp;update(dt);renderer.render(scene,camera)}requestAnimationFrame(animate);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
</script>
</body>
</html>

